    { const char * tb_v3535 = "                if (depth == 8) raw[k] = r[x * ch + k], s[k] = raw[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v3535; }
    { const char * tb_v3536 = "                else if (depth == 16) raw[k] = ((unsigned)r[(x * ch + k) * 2] << 8) | r[(x * ch + k) * 2 + 1], s[k] = raw[k] >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v3536; }
    { const char * tb_v3537 = "                else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3537; }
    { const char * tb_v3538 = "                    unsigned bit = x * depth, v = (r[bit / 8] >> (8 - depth - bit % 8)) & ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3538; }
    { const char * tb_v3539 = "                    raw[k] = v; s[k] = ctype == 3 ? v : v * 255 / ((1u << depth) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3539; }
    { const char * tb_v3540 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v3540; }
    { const char * tb_v3541 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3541; }
    { const char * tb_v3542 = "            unsigned R, G, B, A;\n"; *(const char * *)tb_grow(v_lines) = tb_v3542; }
    { const char * tb_v3543 = "            if (ctype == 3) { unsigned i = s[0] < 256 ? s[0] : 0; R = pal[i][0]; G = pal[i][1]; B = pal[i][2]; A = pal[i][3]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3543; }
    { const char * tb_v3544 = "            else if (ctype == 0 || ctype == 4) { R = G = B = s[0]; A = ctype == 4 ? s[1] : (trns && raw[0] == key[0] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3544; }
    { const char * tb_v3545 = "            else { R = s[0]; G = s[1]; B = s[2]; A = ctype == 6 ? s[3] : (trns && raw[0] == key[0] && raw[1] == key[1] && raw[2] == key[2] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3545; }
    { const char * tb_v3546 = "            px[(size_t)y * w + x] = (A << 24) | (R << 16) | (G << 8) | B;\n"; *(const char * *)tb_grow(v_lines) = tb_v3546; }
    { const char * tb_v3547 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3547; }
    { const char * tb_v3548 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3548; }
    { const char * tb_v3549 = "    free(z.out);\n"; *(const char * *)tb_grow(v_lines) = tb_v3549; }
    { const char * tb_v3550 = "    *pw = (int)w; *ph = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3550; }
    { const char * tb_v3551 = "    return px;\n"; *(const char * *)tb_grow(v_lines) = tb_v3551; }
    { const char * tb_v3552 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3552; }
    { const char * tb_v3553 = "// все картинки программы: точки подряд в одном большом массиве (его же видит видеокарта)\n"; *(const char * *)tb_grow(v_lines) = tb_v3553; }
    { const char * tb_v3554 = "typedef struct { int w, h; uint32_t off; } tb_image;\n"; *(const char * *)tb_grow(v_lines) = tb_v3554; }
    { const char * tb_v3555 = "TB_API tb_image *tb_imgs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3555; }
    { const char * tb_v3556 = "TB_API int tb_nimg = 0, tb_img_dirty = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3556; }
    { const char * tb_v3557 = "TB_API uint32_t *tb_imgpx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3557; }
    { const char * tb_v3558 = "TB_API size_t tb_imgpx_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3558; }
    { const char * tb_v3559 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3559; }
    { const char * tb_v3560 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3560; }
    { const char * tb_v3561 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3561; }
    { const char * tb_v3562 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v3562; }
    { const char * tb_v3563 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3563; }
    { const char * tb_v3564 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3564; }
    { const char * tb_v3565 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3565; }
    { const char * tb_v3566 = "    int w = 0, h = 0; const char *why = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3566; }
    { const char * tb_v3567 = "    uint32_t *px = tb_png(d, (size_t)sz, &w, &h, &why);\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "    free(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
    { const char * tb_v3569 = "    if (!px) { tb_err = why; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3569; }
    { const char * tb_v3570 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3570; }
    { const char * tb_v3571 = "    if (need > 0xFFFFFFFFu) { free(px); tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3571; }
    { const char * tb_v3572 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3572; }
    { const char * tb_v3573 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v3573; }
    { const char * tb_v3574 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v3574; }
    { const char * tb_v3575 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v3575; }
    { const char * tb_v3576 = "    if (!all || !list) { free(px); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3576; }
    { const char * tb_v3577 = "    memcpy(tb_imgpx + tb_imgpx_n, px, (size_t)w * h * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v3577; }
    { const char * tb_v3578 = "    free(px);\n"; *(const char * *)tb_grow(v_lines) = tb_v3578; }
    { const char * tb_v3579 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3579; }
    { const char * tb_v3580 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v3580; }
    { const char * tb_v3581 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3581; }
    { const char * tb_v3582 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3582; }
    { const char * tb_v3583 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3583; }
    { const char * tb_v3584 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3584; }
    { const char * tb_v3585 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3585; }
    { const char * tb_v3586 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3586; }
    { const char * tb_v3587 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v3587; }
    { const char * tb_v3588 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v3588; }
    { const char * tb_v3589 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v3589; }
    { const char * tb_v3590 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v3590; }
    { const char * tb_v3591 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v3591; }
    { const char * tb_v3592 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v3592; }
    { const char * tb_v3593 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v3593; }
    { const char * tb_v3594 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v3594; }
    { const char * tb_v3595 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3595; }
    { const char * tb_v3596 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3596; }
    { const char * tb_v3597 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v3597; }
    { const char * tb_v3598 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3598; }
    { const char * tb_v3599 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v3599; }
    { const char * tb_v3600 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v3600; }
    { const char * tb_v3601 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v3601; }
    { const char * tb_v3602 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3602; }
    { const char * tb_v3603 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v3603; }
    { const char * tb_v3604 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v3604; }
    { const char * tb_v3605 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v3605; }
    { const char * tb_v3606 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3606; }
    { const char * tb_v3607 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v3607; }
    { const char * tb_v3608 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v3608; }
    { const char * tb_v3609 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v3609; }
    { const char * tb_v3610 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v3610; }
    { const char * tb_v3611 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v3611; }
    { const char * tb_v3612 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v3612; }
    { const char * tb_v3613 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3613; }
    { const char * tb_v3614 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v3614; }
    { const char * tb_v3615 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v3615; }
    { const char * tb_v3616 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v3616; }
    { const char * tb_v3617 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v3617; }
    { const char * tb_v3618 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v3618; }
    { const char * tb_v3619 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v3619; }
    { const char * tb_v3620 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v3620; }
    { const char * tb_v3621 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v3621; }
    { const char * tb_v3622 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v3622; }
    { const char * tb_v3623 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3623; }
    { const char * tb_v3624 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3624; }
    { const char * tb_v3625 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v3625; }
    { const char * tb_v3626 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3626; }
    { const char * tb_v3627 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v3627; }
    { const char * tb_v3628 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v3628; }
    { const char * tb_v3629 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3629; }
    { const char * tb_v3630 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
    { const char * tb_v3631 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v3631; }
    { const char * tb_v3632 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3632; }
    { const char * tb_v3633 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v3633; }
    { const char * tb_v3634 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v3634; }
    { const char * tb_v3635 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3635; }
    { const char * tb_v3636 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3636; }
    { const char * tb_v3637 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v3637; }
    { const char * tb_v3638 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3638; }
    { const char * tb_v3639 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v3639; }
    { const char * tb_v3640 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
    { const char * tb_v3641 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3641; }
    { const char * tb_v3642 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3642; }
    { const char * tb_v3643 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v3643; }
    { const char * tb_v3644 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3644; }
    { const char * tb_v3645 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3645; }
    { const char * tb_v3646 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v3646; }
    { const char * tb_v3647 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3647; }
    { const char * tb_v3648 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v3648; }
    { const char * tb_v3649 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3649; }
    { const char * tb_v3650 = "    if (!tb_gpu_back) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3650; }
    { const char * tb_v3651 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3651; }
    { const char * tb_v3652 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3652; }
    { const char * tb_v3653 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3653; }
    { const char * tb_v3654 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3654; }
    { const char * tb_v3655 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3655; }
    { const char * tb_v3656 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3656; }
    { const char * tb_v3657 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v3657; }
    { const char * tb_v3658 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3658; }
    { const char * tb_v3659 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v3659; }
