    { const char * tb_v3688 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3688; }
    { const char * tb_v3689 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3689; }
    { const char * tb_v3690 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3690; }
    { const char * tb_v3691 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3691; }
    { const char * tb_v3692 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3692; }
    { const char * tb_v3693 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v3693; }
    { const char * tb_v3694 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3694; }
    { const char * tb_v3695 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3695; }
    { const char * tb_v3696 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v3696; }
    { const char * tb_v3697 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v3697; }
    { const char * tb_v3698 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3698; }
    { const char * tb_v3699 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v3699; }
    { const char * tb_v3700 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v3700; }
    { const char * tb_v3701 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3701; }
    { const char * tb_v3702 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v3702; }
    { const char * tb_v3703 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3703; }
    { const char * tb_v3704 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
