    { const char * tb_v6015 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6015; }
    { const char * tb_v6016 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v6016; }
    { const char * tb_v6017 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v6017; }
