    { const char * tb_v6019 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6019; }
    { const char * tb_v6020 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6020; }
    { const char * tb_v6021 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v6021; }
    { const char * tb_v6022 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6022; }
    { const char * tb_v6023 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6023; }
    { const char * tb_v6024 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6024; }
    { const char * tb_v6025 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6025; }
    { const char * tb_v6026 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6026; }
    { const char * tb_v6027 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6027; }
    { const char * tb_v6028 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6028; }
    { const char * tb_v6029 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6029; }
    { const char * tb_v6030 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6030; }
    { const char * tb_v6031 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6031; }
    { const char * tb_v6032 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6032; }
    { const char * tb_v6033 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6033; }
    { const char * tb_v6034 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6034; }
    { const char * tb_v6035 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6035; }
