    { const char * tb_v6037 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6037; }
    { const char * tb_v6038 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6038; }
    { const char * tb_v6039 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6039; }
    { const char * tb_v6040 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6040; }
    { const char * tb_v6041 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v6041; }
    { const char * tb_v6042 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6042; }
    { const char * tb_v6043 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v6043; }
    { const char * tb_v6044 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6044; }
    { const char * tb_v6045 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6045; }
    { const char * tb_v6046 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6046; }
    { const char * tb_v6047 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6047; }
    { const char * tb_v6048 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6048; }
    { const char * tb_v6049 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6049; }
    { const char * tb_v6050 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6050; }
    { const char * tb_v6051 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6051; }
    { const char * tb_v6052 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v6052; }
    { const char * tb_v6053 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6053; }
    { const char * tb_v6054 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v6054; }
    { const char * tb_v6055 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6055; }
    { const char * tb_v6056 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v6056; }
    { const char * tb_v6057 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v6057; }
    { const char * tb_v6058 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6058; }
    { const char * tb_v6059 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6059; }
    { const char * tb_v6060 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6060; }
    { const char * tb_v6061 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6061; }
    { const char * tb_v6062 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v6062; }
    { const char * tb_v6063 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6063; }
    { const char * tb_v6064 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v6064; }
    { const char * tb_v6065 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v6065; }
    { const char * tb_v6066 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v6066; }
    { const char * tb_v6067 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v6067; }
    { const char * tb_v6068 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v6068; }
    { const char * tb_v6069 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6069; }
    { const char * tb_v6070 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v6070; }
    { const char * tb_v6071 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6071; }
    { const char * tb_v6072 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6072; }
    { const char * tb_v6073 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6073; }
    { const char * tb_v6074 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6074; }
    { const char * tb_v6075 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6075; }
    { const char * tb_v6076 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6076; }
    { const char * tb_v6077 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6077; }
    { const char * tb_v6078 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6078; }
    { const char * tb_v6079 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6079; }
    { const char * tb_v6080 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6080; }
    { const char * tb_v6081 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6081; }
    { const char * tb_v6082 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6082; }
    { const char * tb_v6083 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v6083; }
    { const char * tb_v6084 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6084; }
    { const char * tb_v6085 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6085; }
    { const char * tb_v6086 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v6086; }
    { const char * tb_v6087 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v6087; }
    { const char * tb_v6088 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6088; }
    { const char * tb_v6089 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v6089; }
    { const char * tb_v6090 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v6090; }
    { const char * tb_v6091 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6091; }
    { const char * tb_v6092 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6092; }
    { const char * tb_v6093 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v6093; }
    { const char * tb_v6094 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v6094; }
    { const char * tb_v6095 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6095; }
    { const char * tb_v6096 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v6096; }
    { const char * tb_v6097 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v6097; }
