    { const char * tb_v6189 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v6189; }
    { const char * tb_v6190 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6190; }
    { const char * tb_v6191 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6191; }
