    { const char * tb_v6194 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v6194; }
    { const char * tb_v6195 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6195; }
    { const char * tb_v6196 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6196; }
    { const char * tb_v6197 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v6197; }
    { const char * tb_v6198 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6198; }
    { const char * tb_v6199 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v6199; }
    { const char * tb_v6200 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v6200; }
    { const char * tb_v6201 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6201; }
    { const char * tb_v6202 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v6202; }
    { const char * tb_v6203 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v6203; }
    { const char * tb_v6204 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v6204; }
    { const char * tb_v6205 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6205; }
