    { const char * tb_v6462 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v6462; }
    { const char * tb_v6463 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6463; }
