    { const char * tb_v6466 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6466; }
    { const char * tb_v6467 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v6467; }
    { const char * tb_v6468 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6468; }
    { const char * tb_v6469 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6469; }
    { const char * tb_v6470 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v6470; }
    { const char * tb_v6471 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6471; }
