    { const char * tb_v6474 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v6474; }
    { const char * tb_v6475 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6475; }
    { const char * tb_v6476 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6476; }
