    { const char * tb_v6518 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v6518; }
    { const char * tb_v6519 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v6519; }
